+import type { CanvasSessionPort } from '../../../../application/mapping/agent/ports';
+
+const exec = promisify(execFile), roots: string[] = [];
+afterEach(async () => { await Promise.all(roots.splice(0).map(root => rm(root, { recursive: true, force: true }))); });
