import { mkdtemp, mkdir, rm, writeFile } from 'node:fs/promises';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, expect, it } from 'vitest';
import { GitPushSource } from '../gitPushSource';
import { GitRepositoryRegistry } from '../../persistence/repositoryRegistry';
import { captureGitHunks } from '../../persistence/repositoryHunks';
import type { RepositoryConnection } from '../../../../domain/core/integrations/pushIntegration';
import { diffSessionRequestSchema } from '../../../../application/mapping/changes/diffSessionWorkflowService';
import { ChangeSessionService } from '../../../../application/mapping/changes/changeSessionService';
import { DiagramChangeSessionStore } from '../../../mapping/changes/diagramChangeSessionStore';
import type { DiagramRepository } from '../../../../application/core/ports/diagramRepository';
import type { CanvasSessionPort } from '../../../../application/mapping/agent/ports';

const exec = promisify(execFile), roots: string[] = [];
afterEach(async () => { await Promise.all(roots.splice(0).map(root => rm(root, { recursive: true, force: true }))); });
async function fixture() {
  const root = await mkdtemp(path.join(tmpdir(), 'push-git-')); roots.push(root);
  const origin = path.join(root, 'origin'), clone = path.join(root, 'clone'), storage = path.join(root, 'storage');
  await mkdir(origin); await mkdir(storage);
  const git = async (cwd: string, ...args: string[]) => (await exec('git', ['-C', cwd, ...args], { env: { ...process.env,
    GIT_AUTHOR_NAME: 'Test', GIT_AUTHOR_EMAIL: 'test@example.com', GIT_COMMITTER_NAME: 'Test', GIT_COMMITTER_EMAIL: 'test@example.com' } })).stdout.trim();
  await git(origin, 'init', '-b', 'main');
  const commit = async (text: string) => {
    await writeFile(path.join(origin, 'app.txt'), `${text}\n`);
    await git(origin, 'add', 'app.txt'); await git(origin, 'commit', '-m', text);
    return git(origin, 'rev-parse', 'HEAD');
  };
  const a = await commit('a');
  await exec('git', ['clone', origin, clone]);
  const b = await commit('b'), c = await commit('c');
  await git(origin, 'checkout', '-b', 'replacement', a);
  const d = await commit('d');
  await writeFile(path.join(storage, 'project.json'), JSON.stringify({ schemaVersion: 1, id: 'project' }));
  const registry = new GitRepositoryRegistry(storage, clone);
  const repository = await registry.register({ path: clone });
  // Local Git transport is injected only in this filesystem fixture; HTTP connection
  // creation requires credential-free HTTPS URLs.
  const connection: RepositoryConnection = { id: 'test', repositoryId: repository.id, enabled: true,
    remoteUrl: origin, external: { provider: 'generic', repositoryKey: 'fixture' } };
  return { root, origin, clone, storage, git, a, b, c, d, registry, connection, source: new GitPushSource(registry) };
}
it('fetches exact missing objects and discovers the complete multi-commit push without moving the checkout', async () => {
  const f = await fixture();
  const resolved = await f.source.resolve(f.connection, { eventId: 'one', ref: 'refs/heads/main', before: f.a, after: f.c });
  expect(resolved).toEqual({ kind: 'update', commits: [f.b, f.c], hasChanges: true });
  expect(await f.git(f.clone, 'rev-parse', 'HEAD')).toBe(f.a);
  const context = await f.registry.resolveContext({ repositoryId: f.connection.repositoryId, commits: resolved.commits, head: f.c, comparisonBase: f.a });
  const hunks = await captureGitHunks(f.clone, context);
  expect(hunks).toHaveLength(1);
  expect(hunks[0]).toMatchObject({ commit: f.c, parent: f.a });
  expect(hunks[0].patch).toContain('-a\n+c');
  expect((await captureGitHunks(f.clone, { repositoryId: context.repositoryId, commits: [f.b, f.c], head: f.c })).map(hunk => hunk.commit)).toEqual([f.b, f.c]);
});
it('handles new branches, divergent force-pushes and rewind-only pushes with correct net patches', async () => {
  const f = await fixture();
  const event = { eventId: 'one', ref: 'refs/heads/main', before: f.c, after: f.d };
  expect(await f.source.resolve(f.connection, { ...event, before: null })).toEqual({ kind: 'new-branch', commits: [f.a, f.d], hasChanges: true });
  expect(await f.source.resolve(f.connection, event)).toEqual({ kind: 'force-push', commits: [f.d], hasChanges: true });
  const rollback = await f.source.resolve(f.connection, { ...event, after: f.a });
  expect(rollback).toEqual({ kind: 'force-push', commits: [], hasChanges: true });
  const request = diffSessionRequestSchema.parse({ requestId: 'rewind', title: 'Rewind', repositoryId: f.connection.repositoryId,
    commits: [], head: f.a, comparisonBase: f.c });
  const repository = new DiagramChangeSessionStore(f.storage);
  const source = { repositories: f.registry, loadProject: async () => ({ id: 'project' }),
    projectCatalogs: { loadRepresentationCatalog: async () => ({ representations: {}, revisions: {} }) } } as unknown as DiagramRepository;
  const changes = new ChangeSessionService(repository, source, { list: () => [] } as unknown as CanvasSessionPort);
  const captured = await changes.capture(request);
  expect(captured.hunks[0].patch).toContain('-c\n+a');
  const created = await changes.create({ title: 'Rewind', requestId: 'rewind' }, captured) as { changeSessionId: string };
  const saved = await changes.get(created.changeSessionId);
  expect(saved).toMatchObject({ commits: [], head: f.a, comparisonBase: f.c });
  expect(saved.diffTree!.hunks).toEqual(captured.hunks);

});
it('captures a new branch against the empty tree and treats equal trees as no-op', async () => {
  const f = await fixture();
  await f.source.resolve(f.connection, { eventId: 'new', ref: 'refs/heads/new', before: null, after: f.c });
  const context = await f.registry.resolveContext({ repositoryId: f.connection.repositoryId, head: f.c, commits: [f.a, f.b, f.c], comparisonBase: null });
  const hunks = await captureGitHunks(f.clone, context);
  expect(hunks[0]).toMatchObject({ status: 'A', parent: null, commit: f.c });
  expect(hunks[0].patch).toContain('+c');
  await f.git(f.origin, 'commit', '--allow-empty', '-m', 'empty');
  const empty = await f.git(f.origin, 'rev-parse', 'HEAD');
  expect(await f.source.resolve(f.connection, { eventId: 'empty', ref: 'refs/heads/replacement', before: f.d, after: empty }))
    .toMatchObject({ kind: 'update', commits: [empty], hasChanges: false });
});

import { createServer, type Server } from 'node:http';
import { execFileSync } from 'node:child_process';
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { expect, it, vi } from 'vitest';
import { DiagramStore } from '../../persistence/store';
import { GitPushSource } from '../gitPushSource';
import { FilePushIntegrationStore } from '../pushIntegrationStore';
import { PushIntegrationService } from '../../../../application/core/integrations/pushIntegrationService';
import { handlePushIntegration } from '../../../../src/server/routes/mapping/integrations/pushIntegrationRoutes';
import { DiagramChangeSessionStore } from '../../../mapping/changes/diagramChangeSessionStore';
import { ChangeSessionService } from '../../../../application/mapping/changes/changeSessionService';
import { AgentDiagrammingSessionService } from '../../../../application/mapping/agent/sessionService';
import { DiffSessionWorkflowService } from '../../../../application/mapping/changes/diffSessionWorkflowService';
import type { DiffSessionRuntime } from '../../../../application/mapping/changes/diffSessionWorkflow';
import { QuickJsAgentRuntime } from '../../../mapping/agent/execRuntime';
import { FileDiffSessionRunStore, createDiffSessionSourceReader } from '../../../mapping/agents/diff-session-create/diffSessionStorage';
import { CanvasSessionBridge } from '../../../mapping/agent/canvasSessionBridge';
import type { MappingDiagramService } from '../../../../application/mapping/diagrams/diagramService';
import { canvasSaveFixture, singleDiagramScene } from '../../../../tests/support/mappingDiagram';
import worker from '../../../../deploy/artifacts-push/worker';

it('forwards an Artifacts push over HTTP through both workflow turns into one ready, persisted DiffSession', async () => {
  const root = await mkdtemp(path.join(tmpdir(), 'push-http-'));
  let server: Server | undefined;
  let workflow: DiffSessionWorkflowService | undefined;
  let agent: AgentDiagrammingSessionService | undefined;
  const bridge = new CanvasSessionBridge();
  try {
    const git = (...args: string[]) => execFileSync('git', ['-C', root, ...args], { encoding: 'utf8' }).trim();
    git('init', '-q', '-b', 'main');
    const commit = async (value: string) => {
      await writeFile(path.join(root, 'app.txt'), `${value}\n`); git('add', 'app.txt');
      git('-c', 'user.name=Test', '-c', 'user.email=test@example.com', 'commit', '-qm', value);
      return git('rev-parse', 'HEAD');
    };
    const before = await commit('Before'), middle = await commit('Middle'), after = await commit('After');
    const store = new DiagramStore(root, path.join(root, 'data'));
    const project = await store.ensureProject({ checkoutRoot: root, repositoryIdentity: '' });
    const repositoryId = project.repositories![0].id;
    const baseline = await store.projectCatalogs.saveMappingDiagram(project.id,
      canvasSaveFixture({ name: 'App', scene: singleDiagramScene('Before') }));
    const changes = new ChangeSessionService(new DiagramChangeSessionStore(store.storeRoot), store, bridge);
    agent = new AgentDiagrammingSessionService(bridge, {} as MappingDiagramService, store, new QuickJsAgentRuntime(), changes);
    const turns: string[] = [];
    // Only model output is controlled. Git, HTTP, storage, proposal tools,
    // version checks, completion validation and workflow sequencing are real.
    const runtime: DiffSessionRuntime = { dispose() {}, async openSession(input) {
      return { sessionId: 'test-agent', dispose() {}, transcript: () => turns,
        async runStep(request) {
          turns.push(request.stepId);
          if (request.stepId === 'analyze') {
            expect(request.prompt).toContain(before);
            expect(request.prompt).toContain(middle);
            expect(request.prompt).toContain(after);
            return { text: 'Replace Before with After.' };
          }
          const call = async (name: string, args: unknown) => input.tools('materialize').find(tool => tool.name === name)!.execute(args);
          const created = await call('create_diagram_change_session', {}) as { changeSessionId: string; canvasId: string; documents: { documentId: string }[] };
          const attached = await call('exec', { requestId: 'attach', code: `return canvas.attach({ canvasId: ${JSON.stringify(created.canvasId)}, documentId: ${JSON.stringify(created.documents[0].documentId)} });` }) as { value: { sessionId: string } };
          await call('exec', { requestId: 'edit', sessionId: attached.value.sessionId, expectedVersion: 0,
            code: 'return nodes.patchDiagram({nodeId: "grid:overview", start: 1, end: 1, patch: "After"});' });
          const session = await changes.get(created.changeSessionId);
          await call('update_diagram_change_session', { changeSessionId: created.changeSessionId, requestId: 'ready', expectedVersion: session.version, status: 'ready' });
          await call('complete_diff_session', {});
          return { text: 'Created', changeSessionId: created.changeSessionId };
        }
      };
    } };
    workflow = new DiffSessionWorkflowService(changes, agent, runtime, new FileDiffSessionRunStore(store.storeRoot),
      { enabled: true, sourceRoot: root, loadPrompts: async () => ({ analyze: 'Analyze', materialize: 'Create' }),
        sourceReader: capture => createDiffSessionSourceReader(store.repositories, capture) });
    const service = new PushIntegrationService(new FilePushIntegrationStore(store.storeRoot), new GitPushSource(store.repositories), workflow, true);
    const token = 'test-integration-token';
    server = createServer((request, response) => {
      void handlePushIntegration(request, response, new URL(request.url!, 'http://localhost'), service, token).catch(error => {
        response.statusCode = 400; response.end(JSON.stringify({ error: error.message }));
      });
    });
    await new Promise<void>(resolve => server!.listen(0, '127.0.0.1', resolve));
    const address = server.address() as { port: number };
    const base = `http://127.0.0.1:${address.port}/api/mapping/integrations`;
    expect((await fetch(`${base}/connections`)).status).toBe(401);
    const headers = { authorization: `Bearer ${token}`, 'content-type': 'application/json' };
    const accountId = 'a'.repeat(32);
    const connected = await fetch(`${base}/connections/test`, { method: 'PUT', headers, body: JSON.stringify({ repositoryId,
      external: { provider: 'artifacts', accountId, namespace: 'default', repoName: 'example' },
      remoteUrl: `https://${accountId}.artifacts.cloudflare.net/git/default/example.git` }) });
    expect(connected.status).toBe(200);
    const event = { type: 'cf.artifacts.repo.pushed', source: { type: 'artifacts.repo', namespace: 'default', repoName: 'example' },
      payload: { ref: 'refs/heads/main', before, after, commits: [{ id: after }], commitsTruncated: true, totalCommitsCount: 2 },
      metadata: { accountId, eventSchemaVersion: 1, eventTimestamp: '2026-10-14T01:02:03Z' } };
    const ack = vi.fn();
    await worker.queue({ messages: [{ body: event, ack, retry() {} }, { body: event, ack, retry() {} }] },
      { PUSH_ENDPOINT: `${base}/connections/test/artifacts`, PUSH_TOKEN: token });
    expect(ack).toHaveBeenCalledTimes(2);
    await vi.waitFor(async () => {
      const runs = await service.generations();
      expect(runs).toHaveLength(1);
      expect(runs[0].error).toBeUndefined();
      expect(runs[0]).toMatchObject({ status: 'completed', commits: [middle, after] });
    }, { timeout: 10000 });
    const [generation] = await (await fetch(`${base}/pushes`, { headers })).json();
    const proposal = await changes.get(generation.changeSessionId);
    expect(proposal).toMatchObject({ status: 'ready', commits: [middle, after], head: after, comparisonBase: before });
    expect(proposal.diffTree!.hunks[0].patch).toContain('-Before\n+After');
    expect(turns).toEqual(['analyze', 'materialize']);
    expect(await changes.list()).toHaveLength(1);
    const catalog = await store.projectCatalogs.loadRepresentationCatalog(project.id);
    expect(catalog.representations[baseline.representation.id].currentRevisionId).toBe(baseline.representation.currentRevisionId);
    const reopened = await new DiagramChangeSessionStore(store.storeRoot).read(project.id, proposal.id);
    expect(reopened.comparisonBase).toBe(before);
    expect((await changes.capture({ baselineChangeSessionId: proposal.id })).context?.comparisonBase).toBe(before);
  } finally {
    if (server) { server.closeAllConnections(); await new Promise<void>(resolve => server!.close(() => resolve())); }
    workflow?.dispose(); agent?.dispose(); bridge.dispose();
    await rm(root, { recursive: true, force: true });
  }
}, 20000);

import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, expect, it, vi } from 'vitest';
import { PushIntegrationService } from '../../../../application/core/integrations/pushIntegrationService';
import { decodeArtifactsPush } from '../../../../application/core/integrations/artifactsPush';
import { repositoryConnectionSchema } from '../../../../domain/core/integrations/pushIntegration';
import type { PushSource, PushWorkflow } from '../../../../application/core/integrations/ports';
import { FilePushIntegrationStore } from '../pushIntegrationStore';

const roots: string[] = [];
afterEach(async () => { await Promise.all(roots.splice(0).map(root => rm(root, { recursive: true, force: true }))); });
const accountId = 'a'.repeat(32), a = 'a'.repeat(40), b = 'b'.repeat(40), c = 'c'.repeat(40);
const connection = repositoryConnectionSchema.parse({ id: 'test', repositoryId: 'repo-local',
  external: { provider: 'artifacts', accountId, namespace: 'default', repoName: 'example' },
  remoteUrl: `https://${accountId}.artifacts.cloudflare.net/git/default/example.git` });
const event = { eventId: 'push-1', ref: 'refs/heads/main', before: a, after: c };
async function setup() {
  const root = await mkdtemp(path.join(tmpdir(), 'push-integration-')); roots.push(root);
  const store = new FilePushIntegrationStore(root);
  const source: PushSource = { validateConnection: vi.fn(async () => {}),
    resolve: vi.fn(async () => ({ kind: 'update' as const, commits: [b, c], hasChanges: true })) };
  const workflow: PushWorkflow = { start: vi.fn(async () => ({ id: 'workflow', status: 'running' as const })),
    get: vi.fn(async () => ({ id: 'workflow', status: 'completed' as const, changeSessionId: 'proposal' })) };
  const service = new PushIntegrationService(store, source, workflow, true);
  await service.connect(connection);
  return { root, store, source, workflow, service };
}
it('creates exactly one workflow for concurrent/repeated deliveries, with all commits and pinned push endpoints', async () => {
  const f = await setup();
  const results = await Promise.all(Array.from({ length: 8 }, () => f.service.receive('test', event)));
  expect(new Set(results.map(result => result.id)).size).toBe(1);
  expect(f.workflow.start).toHaveBeenCalledTimes(1);
  expect(f.workflow.start).toHaveBeenCalledWith(expect.objectContaining({ repositoryId: 'repo-local', commits: [b, c], comparisonBase: a, head: c }));
  expect(await f.service.get(results[0].id)).toMatchObject({ status: 'completed', changeSessionId: 'proposal' });
  const reopened = new PushIntegrationService(new FilePushIntegrationStore(f.root), f.source, f.workflow, true);
  expect(await reopened.receive('test', event)).toMatchObject({ id: results[0].id, changeSessionId: 'proposal' });
  expect(f.workflow.start).toHaveBeenCalledTimes(1);
  await expect(reopened.receive('test', { ...event, after: b })).rejects.toThrow('PUSH_EVENT_ID_CONFLICT');
  expect(await f.service.generations('test')).toHaveLength(1);
});
it('atomically claims an event across independent service instances', async () => {
  const f = await setup();
  const other = new PushIntegrationService(new FilePushIntegrationStore(f.root), f.source, f.workflow, true);
  await Promise.all([f.service.receive('test', event), other.receive('test', event)]);
  expect(f.workflow.start).toHaveBeenCalledTimes(1);
});
it('does not conflate distinct pushes that happen to have the same endpoints', async () => {
  const f = await setup();
  const first = await f.service.receive('test', event);
  const second = await f.service.receive('test', { ...event, eventId: 'another-push' });
  expect(first.id).not.toBe(second.id);
  expect(f.workflow.start).toHaveBeenCalledTimes(2);
});
it('normalizes Artifacts identity, ignores truncated commit hints, and rejects a foreign repository', async () => {
  const raw = { type: 'cf.artifacts.repo.pushed', source: { type: 'artifacts.repo', namespace: 'default', repoName: 'example' },
    payload: { ref: event.ref, before: a, after: c, commits: [{ id: c }], commitsTruncated: true, totalCommitsCount: 2 },
    metadata: { accountId, eventSchemaVersion: 1, eventTimestamp: '2026-10-14T01:02:03Z', eventSubscriptionId: 'one' } };
  const f = await setup();
  const first = await f.service.receive('test', raw, 'artifacts');
  const second = await f.service.receive('test', { ...raw, metadata: { ...raw.metadata, eventSubscriptionId: 'two' } }, 'artifacts');
  expect(first.id).toBe(second.id);
  expect(first.commits).toEqual([b, c]);
  expect(() => decodeArtifactsPush(connection, { ...raw, source: { ...raw.source, repoName: 'foreign' } })).toThrow('does not belong');
  expect(() => decodeArtifactsPush(connection, { ...raw, metadata: { ...raw.metadata, eventSchemaVersion: 2 } })).toThrow();
});
it('skips branch deletion, unchanged refs, tags and net-empty pushes without calling the model', async () => {
  const f = await setup();
  expect(await f.service.receive('test', { ...event, after: '0'.repeat(40) })).toMatchObject({ kind: 'delete', status: 'skipped' });
  expect(await f.service.receive('test', { ...event, eventId: 'same', after: a })).toMatchObject({ status: 'skipped', kind: 'unchanged' });
  expect(await f.service.receive('test', { ...event, eventId: 'tag', ref: 'refs/tags/v1' })).toMatchObject({ status: 'skipped' });
  vi.mocked(f.source.resolve).mockResolvedValue({ kind: 'update' as const, commits: [b, c], hasChanges: false });
  expect(await f.service.receive('test', { ...event, eventId: 'empty' })).toMatchObject({ status: 'skipped', reason: 'Push has no net content changes' });
  expect(f.workflow.start).not.toHaveBeenCalled();
});
it('starts a rollback comparison even when no commits are newly reachable', async () => {
  const f = await setup();
  vi.mocked(f.source.resolve).mockResolvedValue({ kind: 'force-push', commits: [], hasChanges: true });
  expect(await f.service.receive('test', { ...event, before: c, after: a })).toMatchObject({ kind: 'force-push', commits: [], status: 'running' });
  expect(f.workflow.start).toHaveBeenCalledWith(expect.objectContaining({ comparisonBase: c, head: a, commits: [] }));
});
it('stores visible failures, and validates connection identity, secrets and enabled state', async () => {
  const f = await setup();
  vi.mocked(f.source.resolve).mockRejectedValue(Error('Missing commit'));
  expect(await f.service.receive('test', event)).toMatchObject({ status: 'failed', error: 'Missing commit' });
  await expect(f.service.connect({ ...connection, repositoryId: 'other' })).rejects.toThrow('immutable');
  expect(() => repositoryConnectionSchema.parse({ ...connection, remoteUrl: 'https://token:secret@example.com/repo.git' })).toThrow();
  expect(() => repositoryConnectionSchema.parse({ ...connection, remoteUrl: 'https://example.com/repo.git' })).toThrow();
  await f.service.connect({ ...connection, enabled: false });
  await expect(f.service.receive('test', { ...event, eventId: 'disabled' })).rejects.toThrow('disabled');
});

